    /// <param name="path">- base Path</param>
    /// <param name="applicationHandler">- other Request Handler</param>
    /// <param name="options">- options of <c>.mount()</c></param>
    /// <returns>mounted Hono instance</returns>
    /// <example>
    /// <code>
    /// ```ts
    /// import { Router as IttyRouter } from 'itty-router'
    /// import { Hono } from 'hono'
    /// // Create itty-router application
    /// const ittyRouter = IttyRouter()
    /// // GET /itty-router/hello
    /// ittyRouter.get('/hello', () =&gt; new Response('Hello from itty-router'))
    ///
    /// const app = new Hono()
    /// app.mount('/itty-router', ittyRouter.handle)
    /// </code>
    /// <code>
    /// </code>
    /// </example>
    /// <example>
    /// <code>
    /// ```ts
    /// const app = new Hono()
    /// // Send the request to another application without modification.
