type OpenAPIRouteConstructor =
    abstract isRoute: bool with get, set
    [<EmitConstructor>]
    abstract Create: ``params``: RouteOptions -> OpenAPIRoute<obj>

type HonoOpenAPIHandler =
    inherit OpenAPIHandler
    /// <summary>
    /// Gets the Request object from handler arguments.
    /// Must be implemented by subclasses.
    /// </summary>
    abstract getRequest: args: obj[] -> obj
    /// <summary>
    /// Gets URL parameters from handler arguments.
    /// Must be implemented by subclasses.
    /// </summary>
    abstract getUrlParams: args: obj[] -> JS.Record<string, obj>
    /// <summary>
    /// Gets environment bindings from handler arguments.
    /// Must be implemented by subclasses.
    /// </summary>
    abstract getBindings: args: obj[] -> JS.Record<string, obj>

type IttyRouterOpenAPIRouterType<'M> =
    inherit FSharp.CloudEdge.Runtime.Chanfana.OpenAPIRouterType<'M>
    inherit FromIttyRouter.Result2<'M>

type IttyRouterOpenAPIHandler =
    inherit OpenAPIHandler
    /// <summary>
    /// Gets the Request object from handler arguments.
    /// Must be implemented by subclasses.
    /// </summary>
    abstract getRequest: args: obj[] -> obj
    /// <summary>
    /// Gets URL parameters from handler arguments.
    /// Must be implemented by subclasses.
    /// </summary>
    abstract getUrlParams: args: obj[] -> JS.Record<string, obj>
    /// <summary>
    /// Gets environment bindings from handler arguments.
    /// Must be implemented by subclasses.
    /// </summary>
    abstract getBindings: args: obj[] -> JS.Record<string, obj>

[<Fickl.Core.CallableInterface>]
type ContentJson =
    [<Emit("$0($1...)")>]
    abstract Invoke<'T>: schema: ZodType4<'T, obj, FSharp.CloudEdge.Runtime.Zod.ZodTypeInternals<'T, obj>> -> ContentJson.Result<'T>

[<Interface>]
type FilterCondition =
    abstract field: string with get, set
    abstract operator: string with get, set
    abstract value: U3<string, float, bool> option with get, set
    [<ParamObject; Emit("(o => ({...o, \"value\": o[\"value\"] ?? null}))($0)")>]
    static member Create (field: string, operator: string, ?value: U3<string, float, bool>) : FilterCondition = jsNative

[<Interface>]
type ListFilters =
    abstract filters: FilterCondition[] with get, set
    abstract options: ListFilters.Options with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (filters: FilterCondition[], options: ListFilters.Options) : ListFilters = jsNative

[<Interface>]
type Filters =
    abstract filters: FilterCondition[] with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (filters: FilterCondition[]) : Filters = jsNative

[<Interface>]
type UpdateFilters =
    abstract filters: FilterCondition[] with get, set
    abstract updatedData: JS.Record<string, obj> with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (filters: FilterCondition[], updatedData: JS.Record<string, obj>) : UpdateFilters = jsNative

[<Interface>]
type UpdatedData =
    abstract updatedData: JS.Record<string, obj> with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (updatedData: JS.Record<string, obj>) : UpdatedData = jsNative

[<Interface>]
type SerializerContext =
    abstract filters: FilterCondition[] option with get, set
    abstract options: SerializerContext.Options option with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (?filters: FilterCondition[], ?options: SerializerContext.Options) : SerializerContext = jsNative

[<Interface>]
type Model =
    abstract tableName: string with get, set
